export interface PanelHandle<Params = void> {
    open(params: Params): void;
    close(): void;
    setBadge(text: string | null): void;
    setTitle(title: string): void;
}

export interface NodeRef {
    id: string;
}

export interface ViewRef {
    id: string;
}

export interface ProjectRef {
    id: string;
}

export function defineNode<Data = Json>(
    node: {
        id: string;
        title: string;
        icon?: string;
        size?: { width: number; height: number };
        initialData?: Data;
        dataVersion?: number;
        /** `stored` is what an older `dataVersion` kept, which only the extension knows the shape of. */
        migrate?: (stored: Json, fromVersion: number) => Data;
        /** Where "Add" shows. By default the Extensions submenu of the canvas menu, at the spot clicked, and the command palette. */
        addFrom?: Partial<Slots>;
    } & Surface
): void;

export function defineOverlay<Params = void, Answer = void>(overlay: {
    id: string;
    title: string;
    size?: 'sm';
    component: LazyComponent<{ params: Params; close(answer?: Answer): void }>;
}): { open(params: Params): Promise<Answer | null>; close(): void };

export interface ToolCall {
    name: string;
    input: Json;
    output: string | null;
    state: string;
}

export function defineVoiceAction<Input extends object = { [key: string]: Json | undefined }>(action: {
    id: string;
    description: string;
    parameters?: object;
    run(input: Input): string | Promise<string>;
}): void;

export interface SettingField {
    key: string;
    type: 'boolean' | 'text' | 'select';
    label: string;
    description?: string;
    default: boolean | string;
    options?: { value: string; label: string }[];
}

export interface SettingGroup {
    title?: string;
    description?: string;
    fields: SettingField[];
}

export interface AgentInfo {
    provider: string;
    account: string | null;
    status: AgentStatus;
    cwd: string | null;
    branch: string | null;
    worktree: string | null;
}

export interface ChatSummary {
    id: string;
    provider: string;
    status: AgentStatus;
    model: string | null;
    cwd: string;
}

export interface NodeInfo {
    id: string;
    kind: string;
    title: string;
    color: string | null;
    bounds: { x: number; y: number; width: number; height: number };
    groupId: string | null;
    viewId: string;
    machine: string | null;
    linkedTo: string[];
    agent?: AgentInfo;
    path?: string;
    url?: string;
    extension?: { id: string; type: string };
}

export interface FileInfo {
    path: string;
    name: string;
    extension: string;
}

export interface BaseContext {
    project: { id: string; name: string; folder: string | null };
    view: { id: string; kind: string; name: string } | null;
    machine: { id: string };
    theme: 'light' | 'dark';
}

export interface SlotContexts {
    selectionBar: { nodes: NodeInfo[] };
    nodeHeader: { node: NodeInfo };
    /** `nodes` is the selection if the node is in it. */
    nodeMenu: { node: NodeInfo; nodes: NodeInfo[] };
    canvasMenu: { at: { x: number; y: number } };
    viewToolbar: {};
    viewMenu: { target: { id: string; kind: string } };
    panelHeader: { panel: string };
    commandPalette: { nodes: NodeInfo[] };
    sidebarRow: { node: NodeInfo };
    tabMenu: { target: { id: string } };
    emptyCanvas: {};
    startScreen: {};
    projectBanner: {};
    threadHeader: { chat: { id: string }; node: NodeInfo };
    emptyThread: { chat: { id: string } };
    toolActions: { chat: { id: string }; tool: ToolCall };
    fileRowBadge: { file: FileInfo };
    fileBreadcrumb: { file: FileInfo };
    terminalMenu: { node: NodeInfo };
    browserMenu: {};
    textMenu: { text: { id: string } };
    noteToolbar: { node: NodeInfo };
    routineMenu: { routine: { id: string } };
    composer: { chat: { id: string }; node: NodeInfo };
    projectMenu: {};
    sidebarFooter: {};
    editorStatusBar: { file: FileInfo };
    messageActions: { chat: { id: string }; message: { id: string; kind: 'user' | 'assistant'; text: string } };
    lineMenu: { from: NodeInfo; to: NodeInfo };
    fileMenu: { file: FileInfo; files: FileInfo[] };
    editorToolbar: { file: FileInfo };
    editorMenu: { file: FileInfo; files: FileInfo[] };
    diffToolbar: { repository: string };
    terminalToolbar: { node: NodeInfo };
    browserToolbar: { node: NodeInfo; url: string };
}

export interface ActionHandle<Context extends object = object> {
    run(context?: Partial<BaseContext> & Partial<Context>): Promise<void>;
    useRunning(): boolean;
}

export function defineAction<Place extends SlotName>(action: {
    id: string;
    title: string;
    icon?: string;
    /** Like mod+shift+k. Needs mod or alt. It gets the context of the command palette. */
    shortcut?: string;
    slots: Slots<Place>;
    run(context: ContextOf<Place> & { slot: Place; signal: AbortSignal }): void | Promise<void>;
}): ActionHandle<SlotContexts[Place]>;
export function defineAction<Context extends object = {}>(action: {
    id: string;
    title: string;
    icon?: string;
    shortcut?: string;
    run(context: BaseContext & Context & { slot: string; signal: AbortSignal }): void | Promise<void>;
}): ActionHandle<Context>;

export type ServerClient<Server> = {
    [Method in keyof Server]: Server[Method] extends (...args: infer Args) => Promise<infer Value>
        ? ((...args: Args) => Promise<Result<Returned<Value>>>) & { use(...args: Args): Result<Returned<Value>> }
        : never;
};

export interface ClientEvents {
    'node.added': { node: NodeInfo };
    'node.removed': { id: string };
    'node.changed': { node: NodeInfo };
    'selection.changed': { nodes: NodeInfo[] };
    'view.changed': { viewId: string | null };
    'project.opened': { projectId: string };
    'agent.status': { nodeId: string; status: AgentStatus };
    'chat.turnFinished': { chatId: string };
}

export const host: {
    /** Marks work that is no action as busy: a spinner on `nodes` until it is done, which also stops it through the signal. */
    busy<Value>(work: { title: string; nodes?: NodeRef[] }, run: (signal: AbortSignal) => Value | Promise<Value>): Promise<Value>;
    notify(text: string, options?: { tone?: 'neutral' | 'error'; action?: { title: string; run(): void } }): void;
    /** Null when the person closed the picker. */
    pickFolder(initial?: string): Promise<string | null>;
    openSettings(): void;
    confirm(options: { title: string; body: string; danger?: boolean }): Promise<boolean>;
    /** Null when the person dismissed it. */
    prompt(options: { title: string; placeholder?: string; initial?: string }): Promise<string | null>;
    /** Null when the person dismissed it. */
    pick<Item>(options: { title: string; items: readonly Item[]; label(item: Item): string }): Promise<Item | null>;
    openUrl(url: string): void;
    copy(text: string): void;
};

export interface FileEntry {
    path: string;
    name: string;
    kind: 'file' | 'directory' | 'symlink' | 'other';
}

export const files: {
    readText(path: string): Promise<Result<string>>;
    write(path: string, text: string): Promise<Result<void>>;
    list(folder: string): Promise<Result<FileEntry[]>>;
    /** Calls back when the file or anything under the folder changes. Answers how to stop. */
    watch(path: string, listener: () => void): Result<() => void>;
    open(path: string): void;
};

export interface GitFileStatus {
    /** Relative to the root of the repository. */
    path: string;
    state: 'staged' | 'unstaged' | 'untracked' | 'conflicted';
    /** The porcelain letter, such as `M`, `A`, `D` or `?`. */
    status: string;
    added: number;
    deleted: number;
    binary: boolean;
}

export interface GitStatus {
    /** False outside a repository, with everything below empty. */
    repository: boolean;
    root: string | null;
    branch: string | null;
    upstream: string | null;
    ahead: number;
    behind: number;
    files: GitFileStatus[];
    /** More files changed than `files` holds. */
    truncated: boolean;
}

export interface GitFileDiff {
    path: string;
    /** The unified diff, empty for a binary file or one too large. */
    diff: string;
    added: number;
    deleted: number;
    binary: boolean;
    kind: 'add' | 'update' | 'delete' | null;
}

export interface GitCommit {
    hash: string;
    shortHash: string;
    subject: string;
    author: string;
    /** Epoch milliseconds of the author date. */
    at: number;
    refs: string[];
}

export const git: {
    status(options?: { repository?: string }): Promise<Result<GitStatus>>;
    /** What changed in one file of the working tree, or in the index with `staged`. */
    diff(options: { path: string; repository?: string; staged?: boolean }): Promise<Result<GitFileDiff>>;
    /** The newest commits first, 30 by default. */
    log(options?: { repository?: string; limit?: number }): Promise<Result<GitCommit[]>>;
};

export const chats: {
    list(): Promise<Result<ChatSummary[]>>;
    /** The thread as text, as an agent reads it. */
    read(chatId: string): Promise<Result<string>>;
    send(chatId: string, text: string): Promise<Result<void>>;
};

export interface LaunchSummary {
    id: string;
    name: string;
    kind: 'service' | 'task' | 'group';
    /** Null when it has not run since the machine started, and for a group. */
    state: 'starting' | 'running' | 'stopping' | 'exited' | null;
    exitCode: number | null;
    /** Whether a person approved it on this machine; only then does it start. */
    approved: boolean;
    port: number | null;
    url: string | null;
    /** The launches a group starts. */
    members: string[];
}

export interface RoutineSummary {
    id: string;
    title: string;
    kind: 'agent' | 'command' | 'launch';
    approved: boolean;
    paused: boolean;
    /** Epoch milliseconds of its next run, or null when none is due. */
    next: number | null;
    lastRun: { state: 'skipped' | 'starting' | 'running' | 'needsYou' | 'limit' | 'done' | 'failed'; at: number } | null;
}

export interface ArtifactFileInfo {
    name: string;
    mime: string;
    size: number;
}

export interface ArtifactInfo {
    id: string;
    title: string;
    kind: string;
    key: string | null;
    /** Epoch milliseconds. */
    createdAt: number;
}

export interface ArtifactSummary extends ArtifactInfo {
    latest: { id: string; number: number; createdAt: number; files: ArtifactFileInfo[] };
    versions: number;
}

export interface BrowserState {
    node: NodeRef;
    /** Whether anyone has the page open; with nobody, `page` is null. */
    open: boolean;
    page: { url: string; title: string; loading: boolean; canGoBack: boolean; canGoForward: boolean } | null;
    error: string | null;
}

export interface DeviceInfo {
    name: string;
    platform: 'ios' | 'android';
    kind: 'simulator' | 'physical';
    runtime: string;
}

export interface DeviceState {
    node: NodeRef;
    device: DeviceInfo;
    /** False when this machine has no such device right now. */
    present: boolean;
    state: 'booted' | 'shutdown' | 'transitioning' | null;
    /** The size of the last shot, which `tap` counts its pixels in. */
    screen: { width: number; height: number } | null;
    buttons: string[];
    can: { shot: boolean; input: boolean; type: boolean; launch: boolean };
}

export interface MachineActions {
    'launch.list': { input: {}; output: { launches: LaunchSummary[] } };
    /** `launch` is an id, or a name no other launch carries. `tail` keeps the last lines. */
    'launch.read': { input: { launch: string; tail?: number }; output: { id: string; name: string; text: string | null } };
    'launch.start': { input: { launch: string }; output: { id: string; name: string } };
    'launch.restart': { input: { launch: string }; output: { id: string; name: string } };
    'launch.stop': { input: { launch: string }; output: { id: string; name: string; stopping: number } };
    'routine.list': { input: {}; output: { routines: RoutineSummary[] } };
    'routine.run': { input: { routine: string }; output: { id: string; title: string; runId: string } };
    'routine.pause': { input: { routine: string }; output: { id: string; title: string } };
    'routine.resume': { input: { routine: string }; output: { id: string; title: string } };
    'artifact.list': { input: {}; output: { artifacts: ArtifactSummary[] } };
    /** The latest version and its first file unless `version` and `file` say otherwise. `text` is null for a file that is no text. */
    'artifact.read': {
        input: { artifact: string; version?: string; file?: number };
        output: { artifact: ArtifactInfo; version: { id: string; number: number }; file: ArtifactFileInfo; text: string | null; truncated: boolean };
    };
    /** Files sent beforehand under `upload`; the same `key` makes a new version of the same artifact. */
    'artifact.publish': {
        input: {
            upload: string;
            files: { name: string; size: number }[];
            title?: string;
            kind?: 'report' | 'image' | 'build' | 'export' | 'recording' | 'page';
            key?: string;
            requestId: string;
        };
        output: { artifact: ArtifactInfo; version: { id: string; number: number }; existing: boolean };
    };
    'browser.inspect': { input: { node: NodeRef }; output: BrowserState };
    'browser.navigate': { input: { node: NodeRef; url: string }; output: BrowserState };
    'browser.back': { input: { node: NodeRef }; output: BrowserState };
    'browser.forward': { input: { node: NodeRef }; output: BrowserState };
    'browser.reload': { input: { node: NodeRef; hard?: boolean }; output: BrowserState };
    /** `path` is a png on the machine, or null when nobody has the page open. */
    'browser.screenshot': { input: { node: NodeRef }; output: BrowserState & { path: string | null } };
    'device.list': { input: {}; output: { devices: (DeviceInfo & { id: string; state: 'booted' | 'shutdown' | 'transitioning' })[] } };
    'device.inspect': { input: { node: NodeRef }; output: DeviceState };
    /** A png on the machine, outside the project folder. */
    'device.screenshot': { input: { node: NodeRef }; output: { node: NodeRef; path: string; width: number; height: number } };
    /** A pixel of the last shot, counted from its top-left corner. */
    'device.tap': { input: { node: NodeRef; x: number; y: number }; output: { node: NodeRef } };
    /** `app` is a bundle id on iOS or a package name on Android. */
    'device.launch': { input: { node: NodeRef; app: string }; output: { node: NodeRef } };
}

export const launches: {
    list(): Promise<Result<MachineOutput<'launch.list'>>>;
    read(input: MachineInput<'launch.read'>): Promise<Result<MachineOutput<'launch.read'>>>;
    start(input: MachineInput<'launch.start'>): Promise<Result<MachineOutput<'launch.start'>>>;
    restart(input: MachineInput<'launch.restart'>): Promise<Result<MachineOutput<'launch.restart'>>>;
    stop(input: MachineInput<'launch.stop'>): Promise<Result<MachineOutput<'launch.stop'>>>;
};

export const routines: {
    list(): Promise<Result<MachineOutput<'routine.list'>>>;
    run(input: MachineInput<'routine.run'>): Promise<Result<MachineOutput<'routine.run'>>>;
    pause(input: MachineInput<'routine.pause'>): Promise<Result<MachineOutput<'routine.pause'>>>;
    resume(input: MachineInput<'routine.resume'>): Promise<Result<MachineOutput<'routine.resume'>>>;
};

export const artifacts: {
    list(): Promise<Result<MachineOutput<'artifact.list'>>>;
    read(input: MachineInput<'artifact.read'>): Promise<Result<MachineOutput<'artifact.read'>>>;
    publish(input: MachineInput<'artifact.publish'>): Promise<Result<MachineOutput<'artifact.publish'>>>;
};

export const browser: {
    inspect(input: MachineInput<'browser.inspect'>): Promise<Result<MachineOutput<'browser.inspect'>>>;
    navigate(input: MachineInput<'browser.navigate'>): Promise<Result<MachineOutput<'browser.navigate'>>>;
    back(input: MachineInput<'browser.back'>): Promise<Result<MachineOutput<'browser.back'>>>;
    forward(input: MachineInput<'browser.forward'>): Promise<Result<MachineOutput<'browser.forward'>>>;
    reload(input: MachineInput<'browser.reload'>): Promise<Result<MachineOutput<'browser.reload'>>>;
    screenshot(input: MachineInput<'browser.screenshot'>): Promise<Result<MachineOutput<'browser.screenshot'>>>;
};

export const devices: {
    list(): Promise<Result<MachineOutput<'device.list'>>>;
    inspect(input: MachineInput<'device.inspect'>): Promise<Result<MachineOutput<'device.inspect'>>>;
    screenshot(input: MachineInput<'device.screenshot'>): Promise<Result<MachineOutput<'device.screenshot'>>>;
    tap(input: MachineInput<'device.tap'>): Promise<Result<MachineOutput<'device.tap'>>>;
    launch(input: MachineInput<'device.launch'>): Promise<Result<MachineOutput<'device.launch'>>>;
};

export const terminals: {
    /** Needs `terminals.read`. What the terminal shows now. */
    read(terminal: NodeRef): Promise<Result<string>>;
    /** Needs `canvas.write`. Opens a shell and types nothing: only a person types in a terminal. */
    open(options?: { title?: string; cwd?: string; near?: NodeRef[] }): Result<NodeRef>;
};

export type DatabaseValue =
    | string
    | number
    | boolean
    | null
    | { kind: 'binary'; hex: string; length: number }

export const database: {
    connections(): Promise<Result<{ id: string; name: string }[]>>;
    query(connection: string, sql: string): Promise<Result<{ columns: string[]; rows: DatabaseValue[][]; hasMore: boolean }>>;
};

export const views: {
    open(view: ViewRef): void;
    createCanvas(name: string): Result<ViewRef>;
    rename(view: ViewRef, name: string): Result<void>;
};

export interface ContextSource {
    id: string;
    /** Such as `text`, `terminal`, `chat`, `browser`, `file` or `extension`; a newer Ruimte may add one. */
    kind: string;
    title: string;
    text: string;
}

export const context: {
    read(of: { nodes?: NodeRef[]; view?: ViewRef }): Promise<Result<ContextSource[]>>;
};

export const agents: {
    /** Needs `agents.run`. One hidden prompt on a CLI of the person, with the answer whole. */
    run(options: { prompt: string; context?: string[]; provider?: string }): Promise<Result<{ text: string }>>;
    /** Needs `agents.run`. The same, in pieces as the CLI writes them. A failure is the last piece. */
    stream(options: { prompt: string; context?: string[]; provider?: string; signal?: AbortSignal }): AsyncIterable<Result<{ text: string }>>;
    /** Needs `agents.start`. A chat a person sees and can stop, supervised at most: on the canvas in front, or a view of its own in the sidebar with none there. */
    start(options: { prompt?: string; provider?: string; title?: string; near?: NodeRef[] }): Promise<Result<NodeRef>>;
};

export const canvas: {
    createNote(note: { title?: string; text: string; near?: NodeRef[]; color?: NodeColor }): Result<NodeRef>;
    arrange(nodes: NodeRef[], layout: 'row' | 'column' | 'grid'): Result<void>;
    /** A person confirms first; `refused` when they did not. */
    remove(nodes: NodeRef[]): Promise<Result<void>>;
    createFile(path: string, options?: { near?: NodeRef[] }): Result<NodeRef>;
    createBrowser(url: string, options?: { near?: NodeRef[] }): Result<NodeRef>;
    /** A node of this extension's own, by the id it gave `defineNode`. */
    createNode<Data>(type: string, options?: { data?: Data; title?: string; near?: NodeRef[] }): Result<NodeRef>;
    update(node: NodeRef, patch: { title?: string; x?: number; y?: number; width?: number; height?: number }): Result<void>;
    writeNote(node: NodeRef, text: string): Result<void>;
    group(nodes: NodeRef[]): Result<NodeRef>;
    link(from: NodeRef, to: NodeRef): Result<void>;
    unlink(from: NodeRef, to: NodeRef): Result<void>;
    select(nodes: NodeRef[]): void;
    reveal(target: NodeRef): void;
};

export interface NodeRef {
    id: string;
}

export interface ViewRef {
    id: string;
}

export interface ProjectRef {
    id: string;
}

export interface ChatSummary {
    id: string;
    provider: string;
    status: AgentStatus;
    model: string | null;
    cwd: string;
}

export interface ServerEvents {
    /** A chat changed what it is doing. Needs `chats.read`. */
    'chat.status': { chat: ChatSummary };
    /** Something new in a chat's thread; `chats.read` reads it. Needs `chats.read`. */
    'chat.event': { chatId: string };
    /** The agent in a terminal changed what it is doing. Needs `terminals.read`. */
    'session.status': { nodeId: string; status: AgentStatus };
}

export function defineAgentTool<Input extends object = { [key: string]: Json | undefined }>(tool: {
    id: string;
    description: string;
    parameters?: object;
    run(input: Input, context: { caller: string }): string | Promise<string>;
}): void;

export const agents: {
    /** Needs `agents.run`. One hidden prompt on a CLI of the person, with the answer whole. */
    run(options: { prompt: string; context?: string[]; provider?: string }): Promise<Result<{ text: string }>>;
    /** Needs `agents.start`. A chat a person sees, supervised at most: on the canvas `view`, beside `near`, or a view of its own in the sidebar without one. */
    start(options: { project: ProjectRef; view?: ViewRef; near?: NodeRef[]; prompt?: string; provider?: string; title?: string }): Promise<Result<NodeRef>>;
};

export const chats: {
    list(): Promise<Result<ChatSummary[]>>;
    /** The thread as text, as an agent reads it. */
    read(chatId: string): Promise<Result<string>>;
    /** Wakes the chat. At most 20 messages per chat per hour, past which it answers `limit`. */
    send(chatId: string, text: string): Promise<Result<void>>;
};

export const storage: {
    get<Value>(key: string): Promise<Value | undefined>;
    set<Value>(key: string, value: Value): Promise<void>;
    delete(key: string): Promise<void>;
};

export const secrets: {
    get(key: string): Promise<string | undefined>;
    set(key: string, value: string): Promise<void>;
};

export const machine: {
    platform: string;
    dataFolder: string;
    /** An action of the machine in a project, such as `launch.start`, within what your manifest asks for. */
    run<Name extends MachineActionName>(project: ProjectRef, action: Name, input: MachineInput<Name>): Promise<Result<MachineOutput<Name>>>;
};

export function defineLanguageServer(server: {
    name: string;
    command: string;
    args?: string[];
    env?: Record<string, string>;
    languages: string[];
    patterns: string[];
}): Promise<Result<void>>;

export const log: {
    info(message: string): void;
    /** `error` is what a `catch` caught, of any shape. */
    error(message: string, error?: unknown): void;
};

export interface TestNode {
    id: string;
    kind?: string;
    title?: string;
    /** What an agent reads of it: a note's text, a terminal's screen or a chat's thread. */
    text?: string;
    color?: string | null;
    bounds?: { x: number; y: number; width: number; height: number };
    /** The id of the view it is on. */
    view?: string;
    linkedTo?: string[];
    agent?: Partial<AgentInfo>;
    path?: string;
    url?: string;
    /** A node of this extension, by the id it gave `defineNode`, with what `useNodeData` reads. */
    extension?: { type: string; data?: Json };
}

export interface TestHostAnswers {
    /** How the person answers `host.confirm` and the question before `canvas.remove`. Yes by default. */
    confirm?: boolean | ((options: { title: string; body: string }) => boolean);
    /** Null, by default, is a dismissed prompt. */
    prompt?: string | null | ((options: { title: string; placeholder?: string; initial?: string }) => string | null);
    /** The label of the item the person picks, as `label` wrote it. Null, by default, is a dismissed picker. */
    pick?: string | null | ((options: { title: string; labels: string[] }) => string | null);
    pickFolder?: string | null;
    /** What an overlay closes with, by the id it gave `defineOverlay`. Null, by default, is a dismissed one. */
    overlays?: Record<string, (params: never) => unknown>;
    /** `server/` as `useServer` reaches it: methods that answer, or a test server from `createTestServer`. */
    server?: Record<string, (...args: never[]) => unknown> | TestServer<unknown>;
    'agents.run'?(options: { prompt: string; context?: string[]; provider?: string }): Answer<{ text: string }>;
    /** The pieces of the answer, in order. */
    'agents.stream'?(options: { prompt: string; context?: string[]; provider?: string }): Answer<string[]>;
    /** A chat node on the canvas in front by default. */
    'agents.start'?(options: { prompt?: string; provider?: string; title?: string; near?: NodeRef[] }): Answer<NodeRef>;
    'chats.list'?(): Answer<ChatSummary[]>;
    'chats.send'?(chatId: string, text: string): Answer<void>;
    'files.readText'?(path: string): Answer<string>;
    'files.write'?(path: string, text: string): Answer<void>;
    'files.list'?(folder: string): Answer<FileEntry[]>;
    'git.status'?(options: { repository?: string }): Answer<GitStatus>;
    'git.diff'?(options: { path: string; repository?: string; staged?: boolean }): Answer<GitFileDiff>;
    'git.log'?(options: { repository?: string; limit?: number }): Answer<GitCommit[]>;
    'database.connections'?(): Answer<{ id: string; name: string }[]>;
    'database.query'?(connection: string, sql: string): Answer<{ columns: string[]; rows: DatabaseValue[][]; hasMore: boolean }>;
    /** What `context.read` answers; by default the `text` of each node it names, or of every node on the view. */
    'context.read'?(of: { nodes?: NodeRef[]; view?: ViewRef }): Answer<ContextSource[]>;
    /** `launches`, `routines`, `artifacts`, `browser` and `devices`, by the action each call is: `launches.start` is `launch.start`. */
    'machine.run'?: { [Name in MachineActionName]?: (input: MachineInput<Name>, project: ProjectRef) => Answer<MachineOutput<Name>> };
    'usage.limits'?: ReturnType<typeof useUsageLimits>;
}

export interface TestHostOptions {
    /** Over `manifest.json` in the folder the test runs in, such as `{ permissions: {} }` to take every permission away. */
    manifest?: { id?: string; name?: string; permissions?: Record<string, string> };
    /** `client/index.ts` by default, loaded afresh for this host. */
    entry?: string;
    /** The open project, with its views and nodes; the first view is in front. Null for no open project. */
    project?: { id?: string; name?: string; folder?: string | null; views?: { id: string; kind?: string; name?: string }[]; nodes?: TestNode[] } | null;
    /** The ids of the selected nodes. */
    selection?: string[];
    machine?: { id: string };
    theme?: 'light' | 'dark';
    /** Which `locales/<language>.json` `useLocale` reads, over `en.json`. English by default. */
    language?: string;
    /** What a person set, over the defaults of `defineExtensionSettings`. */
    settings?: Record<string, boolean | string>;
    storage?: { computer?: Record<string, Json>; project?: Record<string, Json>; machine?: Record<string, Json> };
    answers?: TestHostAnswers;
}

export interface TestSlotShown {
    title: string;
    /** The Lucide name, or null for none. */
    icon: string | null;
    /** True, or the reason a person reads, when it shows but cannot be pressed. */
    disabled: boolean | string;
    badge: string | null;
    order: number;
}

export interface TestCall {
    /** Its path, such as `canvas.createNote` or `launches.start`. */
    method: string;
    args: unknown[];
    result: Result<unknown>;
}

export interface TestScreen {
    container: HTMLElement;
    /** What the page says, as a person reads it. */
    text(): string;
    /** The innermost element that says `text`, or null. */
    find(text: string): HTMLElement | null;
    /** Clicks the button, link or menu item that says `target`, or the element itself. */
    click(target: string | Element): Promise<void>;
    /** Types into the field whose label, placeholder or name is `target`, or the element itself. */
    type(target: string | Element, text: string): Promise<void>;
    /** Waits until `check` neither throws nor answers false, over turns of the event loop rather than a clock. */
    until(check: () => unknown): Promise<void>;
    unmount(): void;
}

export interface TestDefinition {
    id: string;
    title?: string;
    component?: () => Promise<{ default: ComponentType<never> }>;
    frame?: string;
    [key: string]: unknown;
}

export interface TestHost {
    /** What the extension defined, in order, with the object each `define*` was given. */
    definitions: { kind: string; definition: TestDefinition }[];
    /** A definition by the id it gave, or a throw that lists the ids there are. */
    action(id: string): TestDefinition;
    menu(id: string): TestDefinition;
    widget(id: string): TestDefinition;
    panel(id: string): TestDefinition;
    view(id: string): TestDefinition;
    node(id: string): TestDefinition;
    card(id: string): TestDefinition;
    overlay(id: string): TestDefinition;
    /** What every slot tells at this place, filled with the project, view, machine and theme, and the selection where the place tells it. A `{ id }` of a node of the project becomes its `NodeInfo`. */
    context<Place extends SlotName>(place: Place, extra?: Partial<Record<keyof SlotContexts[Place], unknown>>): ContextOf<Place>;
    /** How an action, menu or widget shows at this place, or null where it does not. An unknown place throws. */
    slot<Place extends SlotName>(definition: object, place: Place, extra?: Partial<Record<keyof SlotContexts[Place], unknown>>): TestSlotShown | null;
    /**
     * Presses an action, or the node of a `defineNode`, at this place as a person would: `refused` where it does not show or is
     * disabled, `failed` with what it threw, which also shows the person an error, as in Ruimte.
     */
    run<Place extends SlotName>(definition: object, place: Place, extra?: Partial<Record<keyof SlotContexts[Place], unknown>>): Promise<Result<void>>;
    /** A menu's rows at this place: `refused` where it does not show, `failed` with what its `items` threw. */
    menuItems<Place extends SlotName>(menu: object, place: Place, extra?: Partial<Record<keyof SlotContexts[Place], unknown>>): Result<TestMenuItem[]>;
    /** Hands a client event to `useEvent` and `onEvent`. */
    fire<Name extends keyof ClientEvents>(name: Name, payload: ClientEvents[Name]): void;
    /** What `emit` in `server/` says, to `useServerEvent`. */
    emit(name: string, payload: Json): void;
    /** Selects these nodes, as a person would, which also fires `selection.changed`. */
    select(ids: string[]): void;
    /** Changes a setting, as a person would. */
    setSetting(key: string, value: boolean | string): void;
    /**
     * Draws a panel, view, node, widget or card, or a component of your own, into the page, and waits for its lazy import and
     * whatever it suspends on. `node` is the node `useNodeData` reads, `params` what a panel or view gets, `context` a widget's.
     * A throw while it draws rejects. Needs a `*.dom.test.tsx` file.
     */
    render(
        drawable: TestDefinition | ComponentType<never>,
        options?: { node?: string; params?: unknown; context?: object; props?: object }
    ): Promise<TestScreen>;
    canvas: {
        /** Every node of the view in front. */
        nodes(): NodeInfo[];
        /** Each note the extension made, in order. */
        notes(): { id: string; title: string; text: string; color: string | null }[];
        /** Each line between two nodes, in order. */
        links(): { from: string; to: string }[];
        /** Each node the extension made, of any kind, as it is now. */
        created(): NodeInfo[];
        selection(): string[];
        revealed(): string[];
    };
    views(): { id: string; kind: string; name: string; active: boolean }[];
    /** What `host.notify` said, and each failure a person was shown. */
    notifications: { text: string; detail?: string; tone: 'neutral' | 'error'; action?: string }[];
    /** Each question the person was asked, with their answer. */
    dialogs: { kind: 'confirm' | 'prompt' | 'pick' | 'folder'; title: string; body?: string; answer: unknown }[];
    /** What opened: a panel, view or overlay of the extension by its id, a file by its path, a url, or settings. */
    opened: { kind: 'panel' | 'view' | 'overlay' | 'file' | 'url' | 'settings'; id?: string; params?: unknown }[];
    /** Each panel's state, by the id it gave `definePanel`. */
    panels: Record<string, { title: string; badge: string | null; open: boolean; params: unknown }>;
    copied: string[];
    server: { calls: TestCall[] };
    agents: { calls: TestCall[] };
    /** Every call that answered a Result, in order. */
    calls: TestCall[];
    /** What `useStorage` holds per scope now, changed in place. */
    storage: { computer: Record<string, Json>; project: Record<string, Json>; machine: Record<string, Json> };
    settings: Record<string, boolean | string>;
    /** Each refusal and failure, as `ruimte extension dev` prints it. */
    logs: string[];
}

export interface TestServerAnswers {
    'agents.run'?(options: { prompt: string; context?: string[]; provider?: string }): Answer<{ text: string }>;
    /** `near` holds only the first node, as the machine only uses that one. */
    'agents.start'?(options: { project: ProjectRef; view?: ViewRef; near?: NodeRef[]; prompt?: string; provider?: string; title?: string }): Answer<NodeRef>;
    'chats.list'?(): Answer<ChatSummary[]>;
    'chats.read'?(chatId: string): Answer<string>;
    'chats.send'?(chatId: string, text: string): Answer<void>;
    'machine.run'?: { [Name in MachineActionName]?: (input: MachineInput<Name>, project: ProjectRef) => Answer<MachineOutput<Name>> };
}

export interface TestServerOptions {
    /** Over `manifest.json` in the folder the test runs in, such as `{ permissions: {} }` to take every permission away. */
    manifest?: { id?: string; permissions?: Record<string, string> };
    /** `server/index.ts` by default. */
    entry?: string;
    storage?: Record<string, Json>;
    secrets?: Record<string, string>;
    answers?: TestServerAnswers;
}

export interface TestAsk {
    method: 'agents.run' | 'agents.start' | 'chats.list' | 'chats.read' | 'chats.send' | 'machine.run' | 'defineLanguageServer';
    args: Json[];
    result: Result<unknown>;
}

type Method<Api, Name extends keyof Api> = Api[Name] extends (...args: infer Args) => Promise<infer Value>
    ? (...args: Args) => Promise<Result<Returned<Value>>>
    : never;

export interface TestServer<Api> {
    /** Calls a method of `server/index.ts` as the client does: its arguments and answer cross as JSON, a throw answers `failed`. */
    call<Name extends keyof Api & string>(method: Name, ...args: Parameters<Method<Api, Name>>): ReturnType<Method<Api, Name>>;
    /** What `storage` and `secrets` hold now, changed in place. */
    storage: Record<string, Json>;
    secrets: Record<string, string>;
    /** A clock of its own, from 0: `advance('5m')` runs every `schedule` task that falls due on the way, in order, and waits for each. */
    clock: { now(): number; advance(duration: string | number): Promise<void> };
    /** Hands a machine event to `onEvent`, if the manifest has its permission, as the machine would. */
    fire<Name extends keyof ServerEvents>(name: Name, payload: ServerEvents[Name]): void;
    /** What `emit` said, in order. */
    emitted: { name: string; payload: Json }[];
    /** What `server/` asked the machine, in order. */
    asked: TestAsk[];
    /** What `defineLanguageServer` added. */
    languageServers: object[];
    /** What `log` wrote, and every refusal, as `ruimte extension dev` prints it. */
    logs: string[];
    /** An agent's call of a tool `defineAgentTool` named, by the id it gave, answered in text. */
    tool(id: string): { run(input?: object, context?: { caller?: string }): Promise<string> };
    /** What an agent reads of a node of this type along a line. */
    nodeContext(nodeType: string, data: Json): Promise<{ text: string }[]>;
}
